import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Datenschutzerklärung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy.md","filePath":"de/guide/privacy.md","lastUpdated":1793173149000}`),a={name:`de/guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="datenschutzerklarung" tabindex="-1">Datenschutzerklärung <a class="header-anchor" href="#datenschutzerklarung" aria-label="Permalink to “Datenschutzerklärung”">​</a></h1><p>Sudoku ist eine Offline-First-Anwendung mit optionalen Cloud-Funktionen. Diese Seite erläutert, welche Daten die App gegebenenfalls erhebt und wie sie verwendet werden.</p><h2 id="offline-kern-—-keine-datenerhebung-fur-das-spielen" tabindex="-1">Offline-Kern — keine Datenerhebung für das Spielen <a class="header-anchor" href="#offline-kern-—-keine-datenerhebung-fur-das-spielen" aria-label="Permalink to “Offline-Kern — keine Datenerhebung für das Spielen”">​</a></h2><ul><li>Das Kern-Rätselspiel ist vollständig offline spielbar. Für das Spielen ist kein Netzwerkzugriff erforderlich.</li><li>Alle Spieldaten — Einstellungen, Spielstand, Notizen und Statistiken — werden lokal auf Ihrem Gerät gespeichert.</li><li>Es gibt keine Werbung, keine Analyse und keine Tracking-SDKs von Dritten.</li></ul><h2 id="optionale-cloud-funktionen" tabindex="-1">Optionale Cloud-Funktionen <a class="header-anchor" href="#optionale-cloud-funktionen" aria-label="Permalink to “Optionale Cloud-Funktionen”">​</a></h2><h3 id="icloud-synchronisierung-cloudkit" tabindex="-1">iCloud-Synchronisierung (CloudKit) <a class="header-anchor" href="#icloud-synchronisierung-cloudkit" aria-label="Permalink to “iCloud-Synchronisierung (CloudKit)”">​</a></h3><p>Wenn Sie sich bei iCloud anmelden und die Synchronisierung aktivieren:</p><ul><li>Spielstände, Statistiken, Einstellungen und Fortschritte bei täglichen Herausforderungen werden über Apples CloudKit-Dienst mit Ihrem persönlichen <strong>iCloud-Account</strong> synchronisiert.</li><li>Daten werden bei der Übertragung und im Ruhezustand durch Apples Infrastruktur verschlüsselt.</li><li>Nur Sie können mit Ihrer Apple-ID auf Ihre synchronisierten Daten zugreifen.</li><li>Diese Funktion ist vollständig optional — die App funktioniert auch ohne sie einwandfrei.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Wenn Sie sich bei Game Center anmelden:</p><ul><li>Ranglistenpunkte (beste Lösungszeiten je Schwierigkeitsgrad) können in öffentlichen Ranglisten veröffentlicht werden.</li><li>Der Erfolgsfortschritt wird von Apples Game-Center-Dienst erfasst.</li><li>Ihr Game-Center-Anzeigename ist für andere Spieler in den Ranglisten sichtbar.</li><li>Diese Funktion ist vollständig optional.</li></ul><h2 id="der-einzige-weitere-netzwerkzugriff-„weitere-apps" tabindex="-1">Der einzige weitere Netzwerkzugriff: „Weitere Apps“ <a class="header-anchor" href="#der-einzige-weitere-netzwerkzugriff-„weitere-apps" aria-label="Permalink to “Der einzige weitere Netzwerkzugriff: „Weitere Apps“”">​</a></h2><p>Die einzige Nicht-Cloud-Netzwerkfunktion ist der optionale Bereich <strong>„Weitere Apps“</strong> in den Einstellungen, der eine Liste weiterer Apps von unseren Servern abruft. Diese Funktion:</p><ul><li>wird nur aktiv, wenn Sie zu Einstellungen → Weitere Apps navigieren.</li><li>ruft eine schlanke Liste von App-Namen und Links ab — es werden keine personenbezogenen Daten gesendet oder gespeichert.</li><li>kann vollständig ignoriert werden und beeinflusst das Spiel in keiner Weise.</li></ul><h2 id="was-wir-nicht-erheben" tabindex="-1">Was wir nicht erheben <a class="header-anchor" href="#was-wir-nicht-erheben" aria-label="Permalink to “Was wir nicht erheben”">​</a></h2><ul><li>Wir erheben keine personenbezogenen Daten, Dateien, Bilder oder Browserverläufe.</li><li>Wir senden keine Spieldaten an externe Server (außer wie oben für iCloud/Game Center beschrieben).</li><li>Wir binden keine Analyse- oder Werbe-SDKs von Dritten ein.</li><li>Wir nutzen keine Dienste für Absturzberichte oder Telemetrie.</li></ul><h2 id="berechtigungen" tabindex="-1">Berechtigungen <a class="header-anchor" href="#berechtigungen" aria-label="Permalink to “Berechtigungen”">​</a></h2><p>Sudoku benötigt nur wenige Berechtigungen:</p><ul><li><strong>iCloud</strong> (optional): zur Synchronisierung von Spieldaten zwischen Geräten über CloudKit.</li><li><strong>Game Center</strong> (optional): für Ranglisten und Erfolge.</li><li><strong>Netzwerk</strong> (optional): für iCloud-Synchronisierung, Game Center und „Weitere Apps“.</li></ul><p>Es werden keine Berechtigungen für Standort, Kontakte, Kamera, Mikrofon oder andere datenschutzsensible Bereiche angefordert.</p><h2 id="datenspeicherung" tabindex="-1">Datenspeicherung <a class="header-anchor" href="#datenspeicherung" aria-label="Permalink to “Datenspeicherung”">​</a></h2><ul><li>Lokale Daten verbleiben auf Ihrem Gerät, bis Sie die App deinstallieren oder zurücksetzen.</li><li>Mit iCloud synchronisierte Daten unterliegen Apples iCloud-Aufbewahrungsrichtlinien.</li><li>Game-Center-Daten unterliegen Apples Game-Center-Richtlinien.</li></ul><h2 id="datenschutzanfragen" tabindex="-1">Datenschutzanfragen <a class="header-anchor" href="#datenschutzanfragen" aria-label="Permalink to “Datenschutzanfragen”">​</a></h2><p>Da Sudoku alle Daten lokal (und optional in Ihrem persönlichen iCloud) speichert, gibt es keine serverseitigen Daten, die wir kontrollieren oder auf die wir zugreifen. So löschen Sie alle App-Daten:</p><ul><li><strong>Deinstallieren Sie die App</strong> auf Ihrem Gerät bzw. Ihren Geräten.</li><li><strong>iCloud-Daten zurücksetzen</strong>: Unter Einstellungen → [Ihr Name] → iCloud → Account-Speicher verwalten → Sudoku → Daten löschen.</li><li><strong>Lokales Zurücksetzen auf dem Mac</strong>: Hinweise zum Entfernen des Containers finden Sie in der Anleitung zur Problembehandlung.</li></ul><h2 id="datenschutz-fur-kinder" tabindex="-1">Datenschutz für Kinder <a class="header-anchor" href="#datenschutz-fur-kinder" aria-label="Permalink to “Datenschutz für Kinder”">​</a></h2><p>Sudoku erhebt von niemandem aktiv personenbezogene Daten, auch nicht von Kindern. Die App erfordert keine Konten, keine Chat-Funktionen und keine sozialen Netzwerke.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to “Kontakt”">​</a></h2><p>Bei Fragen zum Datenschutz eröffnen Sie ein Issue im Projekt-Repository (<a href="https://github.com/sudoku-pro/sudoku-site" target="_blank" rel="noreferrer">https://github.com/sudoku-pro/sudoku-site</a>) oder kontaktieren Sie uns unter <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};